"""Summary tables, manifest and comparison figure from saved CSVs only. No models, no GPU, no test gate."""
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import common as C

# (requirement, stage, output file under results/<mode>/, R2, R3, R4, generative task, discriminative task)
MANIFEST = [
    ("data audit and quality logs", 1, "quality/", 1, 0, 0, 0, 0),
    ("class and lot balance, distributions", 2, "eda/", 1, 0, 0, 0, 0),
    ("feature dictionary, validity, outliers", 2, "eda/", 1, 0, 0, 0, 0),
    ("feature ranking and stability", 3, "features/", 1, 1, 0, 0, 1),
    ("clustering: k-means and Gaussian mixture", 4, "cluster/", 1, 0, 0, 1, 0),
    ("table baselines: NB, GMM, tree, logreg, HGB", 5, "baselines/val_results.csv", 0, 1, 0, 1, 1),
    ("baseline tuning grid and shuffled-label control", 5, "baselines/grid.csv", 0, 1, 0, 0, 1),
    ("MLP and SmallCNN, three seeds", 6, "neural/curves.csv", 0, 0, 1, 0, 1),
    ("neural tuning and shuffled-label control", 6, "neural/tuning_cnn.csv", 0, 0, 1, 0, 1),
    ("model comparison with intervals", 7, "compare/test_metrics.csv", 0, 1, 1, 0, 1),
    ("paired tests between models", 7, "compare/test_mcnemar.csv", 0, 1, 1, 0, 1),
    ("per-class recall and confusion", 7, "compare/test_recall.csv", 0, 1, 1, 0, 1),
    ("calibration and confidence floors", 8, "routing/val_calibration.csv", 0, 1, 1, 0, 1),
    ("familiarity gates and routing chain", 8, "routing/test_routes.csv", 0, 1, 1, 1, 1),
    ("late-lot hold-out recall", 9, "robustness/late_recall.csv", 0, 1, 1, 0, 1),
    ("late-lot confidence chain", 9, "robustness/late_chain.csv", 0, 1, 1, 0, 1),
    ("grey-world tint arm", 9, "robustness/greyworld_results.csv", 0, 0, 1, 0, 1),
    ("single-image prediction", 10, "src/predict.py", 0, 0, 0, 0, 1),
]
COLS = ["requirement", "stage", "output_file", "covers_R2", "covers_R3", "covers_R4", "generative_task", "discriminative_task"]


def read(p):
    return pd.read_csv(p) if p.exists() else None


def summary():
    rows = []
    cmp = C.RES / "compare"
    for sp in ("test", "val"):
        M = read(cmp / f"{sp}_metrics.csv")
        S = read(cmp / f"{sp}_seed_spread.csv")
        if M is None: continue
        g = M.groupby(["model", "featureset"]).agg(n=("n", "first"), seeds=("seed", "size"), accuracy=("accuracy", "mean"), acc_lo=("acc_lo", "mean"),
                                                   acc_hi=("acc_hi", "mean"), macro_f1=("macro_f1", "mean"), f1_lo=("f1_lo", "mean"), f1_hi=("f1_hi", "mean")).reset_index()
        g.insert(0, "split", sp)
        if S is not None:
            g = g.merge(S[["model", "featureset", "acc_sd", "f1_sd"]], on=["model", "featureset"], how="left")
        rows.append(g)
    vr = read(C.RES / "baselines" / "val_results.csv")
    if not rows and vr is not None:           # no comparison yet: fall back to tuning-time validation results
        rows.append(vr.assign(split="val_tuning")[["split", "model", "featureset", "val_accuracy", "val_macro_f1"]].rename(
            columns={"val_accuracy": "accuracy", "val_macro_f1": "macro_f1"}))
    return pd.concat(rows, ignore_index=True) if rows else pd.DataFrame(columns=["split", "model", "featureset", "accuracy", "macro_f1"])


def figure(S):
    T = S[S.split == "test"] if (S.split == "test").any() else S
    if T.empty or "acc_lo" not in T:
        print("no comparison metrics yet; figure skipped")
        return
    T = T.sort_values("accuracy")
    lab = T.model + ":" + T.featureset
    fig, ax = plt.subplots(figsize=(7, 0.32 * len(T) + 1.5))
    ax.errorbar(T.accuracy, range(len(T)), xerr=[T.accuracy - T.acc_lo, T.acc_hi - T.accuracy], fmt="o", capsize=3)
    ax.set_yticks(range(len(T)), lab)
    ax.set(xlabel=f"Accuracy with 95% bootstrap interval (n={int(T.n.iloc[0])})", title="Model comparison")
    C.savefig(fig, "summary_comparison")


def main():
    S = summary()
    p = C.RES.parent / "SUMMARY.csv" if not C.SMOKE else C.RES / "SUMMARY.csv"
    p.parent.mkdir(parents=True, exist_ok=True)
    S.to_csv(p, index=False); C.wrote(p)
    M = pd.DataFrame(MANIFEST, columns=COLS)
    M["exists"] = [(C.ROOT / f).exists() if f.startswith("src/") else (C.RES / f).exists() for f in M.output_file]
    mp = p.with_name("MANIFEST.csv")
    M.to_csv(mp, index=False); C.wrote(mp)
    figure(S)


if __name__ == "__main__":
    main()
